import sys
import io
from click.testing import CliRunner
from click import command, echo_via_pager

@command()
def cli():
    echo_via_pager("Hello, Click!")

runner = CliRunner()
# Let's check what sys.stdout is *during* invoke
@command()
def cli2():
    print(f"During: {sys.stdout}")
    print(f"During buffer: {sys.stdout.buffer}")
    echo_via_pager("Hello, Click!")

try:
    runner.invoke(cli2)
except Exception as e:
    print(f"Exception: {e}")

